$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('DecimalThrowingProvider'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$builder=$assembly.DefineDynamicModule('Main').DefineType('ThrowingProvider',[Reflection.TypeAttributes]'Public,Sealed');$builder.AddInterfaceImplementation([IFormatProvider]);$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public)|Out-Null;$method=$builder.DefineMethod('GetFormat',[Reflection.MethodAttributes]'Public,Virtual,Final,HideBySig,NewSlot',[object],[type[]]@([type]));$il=$method.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'provider failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$builder.DefineMethodOverride($method,[IFormatProvider].GetMethod('GetFormat'));$throwing=[Activator]::CreateInstance($builder.CreateType())
$custom=[Globalization.NumberFormatInfo]::new();$custom.NegativeSign='~';$custom.PositiveSign='^';$custom.NumberDecimalSeparator='@';$custom.NumberGroupSeparator='_';$custom.NumberGroupSizes=[int[]]@(2,3);$custom.CurrencySymbol='USD';$custom.CurrencyDecimalSeparator=':';$custom.CurrencyGroupSeparator="'";$custom.CurrencyGroupSizes=[int[]]@(3,2);$custom.CurrencyPositivePattern=2;$custom.CurrencyNegativePattern=14;$custom.NumberNegativePattern=4;$custom.PercentSymbol='%!'
$supplementary=[Globalization.NumberFormatInfo]$custom.Clone();$supplementary.NegativeSign=-join [char[]]@(0xd83d,0xde80);$supplementary.PositiveSign=[string][char]0xff0b;$supplementary.NumberDecimalSeparator=[string][char]0x066b;$supplementary.NumberGroupSeparator=[string][char]0x202f;$supplementary.CurrencySymbol=-join [char[]]@(0x20ac,0xd83d,0xdcb7);$supplementary.CurrencyGroupSeparator=[string][char]0x2009;$supplementary.PercentSymbol=[string][char]0x066a
$malformed=[Globalization.NumberFormatInfo]$custom.Clone();$malformed.NegativeSign=[string][char]0xd800;$malformed.PositiveSign=[string][char]0xdc00;$malformed.CurrencySymbol=-join [char[]]@(0x75,0xd800,0x76,0xdc00);$malformed.PercentSymbol=[string][char]0xdc00
function New-DecimalUtf8Formatter(){
 $span=[type]'System.Span[byte]';$bridge=[Reflection.Emit.DynamicMethod]::new('DecimalUtf8SliceTryFormat',[bool],[type[]]@([object],[byte[]],[int],[int],[int[]],[string],[IFormatProvider]));$il=$bridge.GetILGenerator()
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Castclass,[IUtf8SpanFormattable]);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$span.GetConstructor([type[]]@([byte[]],[int],[int])))
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int]);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Call,[MemoryExtensions].GetMethod('AsSpan',[type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[IUtf8SpanFormattable].GetMethod('TryFormat'));$il.Emit([Reflection.Emit.OpCodes]::Ret)
