$formatter=New-DecimalUtf8Formatter;$formattable=[IFormattable].GetMethod('ToString',[type[]]@([string],[IFormatProvider]));$buffers=[Collections.Generic.List[object]]::new();$references=[Collections.Generic.List[object]]::new()
for($index=0;$index -lt $plan.bits.Count;$index++){$value=[decimal]::new([int[]]$plan.bits[$index]);foreach($format in $plan.formats){foreach($profile in $plan.providers){$provider=$null;switch($profile){'invariant'{$provider=[Globalization.NumberFormatInfo]::InvariantInfo};'custom'{$provider=$custom};'supplementary'{$provider=$supplementary};'malformed'{$provider=$malformed};'throwing'{$provider=$throwing}};$arguments=[object[]]::new(2);$arguments[0]=$format;$arguments[1]=$provider
 try{$text=[string]$formattable.Invoke($value,$arguments);$encoded=[Text.Encoding]::UTF8.GetBytes($text);$reference=[ordered]@{ok=$true;textUnits=[int[]][char[]]$text;bytes=[int[]]$encoded};$length=$encoded.Length;$capacities=@(0,1,[Math]::Max(0,$length-1),$length,($length+1))|Sort-Object -Unique}catch{$reference=Failure $_;$capacities=@(0,1,3,7,32)};$references.Add([ordered]@{index=$index;format=$format;provider=$profile;result=$reference})
 foreach($capacity in $capacities){foreach($route in $plan.routes){$offset=if($route -eq 'array'){0}else{3};$suffix=if($route -eq 'array'){0}else{4};$buffer=[byte[]]::new($capacity+$offset+$suffix);for($slot=0;$slot -lt $buffer.Length;$slot++){$buffer[$slot]=0xa5};$written=[int[]]@(99)
  try{$actual=$formatter.Invoke($value,$buffer,$offset,$capacity,$written,$format,$provider);$result=[ordered]@{ok=$true;value=$actual}}catch{$result=Failure $_}
