$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';utf8Assignable=[IUtf8SpanFormattable].IsAssignableFrom([decimal]);charAssignable=[ISpanFormattable].IsAssignableFrom([decimal]);references=$references.ToArray();buffers=$buffers.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 22 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS Decimal UTF8 span capture: $($buffers.Count) buffers and 1440 native string/UTF8 references"
